1	import type { StorageProvider as StorageProviderId } from "@paperclipai/shared";
2	
3	/**
4	 * Local copies of the StorageProvider interface types from
5	 * `server/src/storage/types.ts`. We duplicate only the shapes needed here
6	 * because importing Node-typed server modules into a Worker bundle would pull
7	 * in `node:stream` and other Node-only dependencies.
8	 *
9	 * Keep these in sync with `server/src/storage/types.ts`.
10	 */
11	export interface PutObjectInput {
12	  objectKey: string;
13	  body: Uint8Array | ArrayBuffer;
14	  contentType: string;
15	  contentLength: number;
16	}
17	
18	export interface GetObjectInput {
19	  objectKey: string;
20	}
21	
22	export interface GetObjectResult {
23	  /** ReadableStream — Workers environment returns Web Streams, not Node Readable. */
24	  stream: ReadableStream;
25	  contentType?: string;
26	  contentLength?: number;
27	  etag?: string;
28	  lastModified?: Date;
29	}
